TLM.f("Sancti/08-08",{"officium":"Ss. Cyriaci, Largi et Smaragdi Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","sections":{"Introitus":[{"k":"ref","la":"Ps 33:10-11"},{"k":"text","la":"Timéte Dóminum, omnes sancti ejus, quóniam nihil deest timéntibus eum: dívites eguérunt et esuriérunt: inquiréntes autem Dóminum non defícient omni bono."},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Timéte Dóminum, omnes sancti ejus, quóniam nihil deest timéntibus eum: dívites eguérunt et esuriérunt: inquiréntes autem Dóminum non defícient omni bono."}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua sanctórum Mártyrum tuórum Cyriáci, Largi et Smarágdi sollemnitáte lætíficas: concéde propítius; ut, quorum natalítia cólimus, virtútem quoque passiónis imitémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Thessalonicénses"},{"k":"ref","la":"1 Thess 2:13-16"},{"k":"text","la":"Fratres: Grátias ágimus Deo sine intermissióne: quóniam, cum accepissétis a nobis verbum audítus Dei, accepístis illud, non ut verbum hóminum, sed - sicut est vere - verbum Dei, qui operátur in vobis, qui credidístis. Vos enim imitatóres facti estis, fratres, ecclesiárum Dei, quæ sunt in Judæa in Christo Jesu: quia éadem passi estis et vos a contribúlibus vestris, sicut et ipsi a Judæis: qui et Dóminum occidérunt Jesum et Prophétas: et nos persecúti sunt, et Deo non placent, et ómnibus homínibus adversántur, prohibéntes nos géntibus loqui, ut salvæ fiant, ut ímpleant peccáta sua semper: pervénit enim ira Dei super illos usque in finem."}],"Graduale":[{"k":"ref","la":"Ps 33:10; 33:11"},{"k":"text","la":"Timéte Dóminum, omnes sancti ejus: quóniam nihil deest timéntibus eum. v. Inquiréntes autem Dóminum, non defícient omni bono."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Sap 3:7"},{"k":"text","la":"Fulgébunt justi, et tamquam scintíllæ in arundinéto current in ætérnum. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Sap 3:7"},{"k":"text","la":"Fulgébunt justi, et tamquam scintíllæ in arundinéto discúrrent in ætérnum."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flebant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum"},{"k":"ref","la":"Marc 16:15-18"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Eúntes in mundum univérsum, prædicáte Evangélium omni creatúræ. Qui credíderit, et baptizátus fúerit, salvus erit: qui vero non credíderit, condemnábitur. Signa autem eos, qui credíderint, hæc sequéntur: In nómine meo dæmónia ejícient: linguis loquéntur novis: serpéntes tollent: et si mortíferum quid bíberint, non eis nocébit: super ægros manus impónent, et bene habébunt."}],"Offertorium":[{"k":"ref","la":"Ps 31:11"},{"k":"text","la":"Lætámini in Dómino et exsultáte, justi: et gloriámini, omnes recti corde."}],"Secreta":[{"k":"text","la":"Accépta sit in conspéctu tuo, Dómine, nostra devótio: et ejus nobis fiat supplicatióne salutáris, pro cujus sollemnitáte defértur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 16:17; 16:18"},{"k":"text","la":"Signa autem eos, qui in me credunt, hæc sequéntur: dæmónia ejícient: super ægros manus impónent, et bene habébunt."}],"Postcommunio":[{"k":"text","la":"Refécti participatióne múneris sacri, quǽsumus, Dómine, Deus noster: ut, cujus exséquimur cultum, intercedéntibus sanctis Martýribus tuis Cyríaco, Largo et Smarágdo, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"d59970799c28bf18":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ godišnjom svetkovinom svetih svojih mučenika Cirijaka, Larga i Smaragda, daj milostivo, da nasljedujemo krepost mučeništva onih kojih rođendan slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji nas razveseljuješ godišnjom svetkovinom svojih svetih mučenika Larga, Ciriaka i Smaragda, dopusti nam milostivo, da nasljedujemo krepost trpljenja onih, kojih rođeni dan slavimo, po G. n.","knRef":"Kniewald 1942, str. 672–673 (snimka 337) (OCR)"},"9618e1534aadf103":{"t":"Bio ti, Gospodine, ugodan naš odani dar, i neka nam bude spasonosan po molitvi onoga o čijoj se svetkovini prikazuje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"49dca572c2904279":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni sudjelovanjem u svetom daru molimo, Gospodine Bože naš, da po zagovoru svetih mučenika Cirijaka, Larga i Smaragda osjetimo učinak onoga što u svetom činu obavljamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → tuis","kn":"Okrijepljeni dioništvom svetih darova molimo, Gospodine, Bože naš, da zagovorom Tvojih svetih mučenika Ciriaka, Larga i Smaragda osjetimo učinak onoga, što časno izvršni emo. po G. n.","knRef":"Kniewald 1942, str. 672–673 (snimka 337) (OCR)"}}});
